 static int stage,age,ticks,unit,commandFrame;static boolean done,feedbackComplete,walkingChecked;static Path root;static CompletableFuture<?> work;static final List<String> checks=new ArrayList<>();static Vec3 goal,before,walkStart;static long command,response=-1,translationResponse=-1;static double facing;
 static void next(int n){stage=n;age=0;GeneralsMod.LOG.info("Version oracle case {}",n);}
 static void click(Minecraft mc,String label){var b=MenuScreens.active(mc.screen).children().stream().filter(w->w instanceof Button button&&(button.getMessage().getString().equals(label)||button.getMessage().getString().equals(L.s(label)))).map(w->(Button)w).findFirst().orElseThrow(()->new IllegalStateException("Missing action "+label+" in "+MenuScreens.active(mc.screen).getClass().getName()+" "+MenuScreens.active(mc.screen).children().stream().filter(w->w instanceof Button).map(w->((Button)w).getMessage().getString()).toList()));var e=new MouseButtonEvent(b.getX()+3,b.getY()+3,new MouseButtonInfo(0,0));var owner=MenuScreens.active(mc.screen);if(!owner.mouseClicked(e,false))throw new IllegalStateException("New mouse event rejected");owner.mouseReleased(e);}
 static void tick(Minecraft mc){if(done)return;age++;ticks++;try{if(stage==2)NativeVersionReuseBench.advanceOwnedWorld(mc,label->click(mc,label));
  if(ticks>20*180)throw new IllegalStateException("Version oracle timeout "+stage);if(MenuScreens.active(mc.screen) instanceof GeneralsFailureScreen&&!NativeVersionMenusBench.recoveryPreview())throw new IllegalStateException("Engine failure "+NativeNetworkClient.message);
  if(stage==0&&ticks>30){root=NativeVersionReuseBench.root(mc);System.setProperty("generalsmc.nativeRoot",root.toString());mc.options.guiScale().set(2);mc.options.pauseOnLostFocus=false;mc.setScreen(new GeneralsGuide(new GeneralsSetupScreen(null)));click(mc,"Далее");if(((GeneralsGuide)MenuScreens.active(mc.screen)).step!=1)throw new IllegalStateException("New mouse events did not advance guide");click(mc,"Закрыть гайд");checks.add("Guide buttons handle actual modern Minecraft mouse event objects");if(!GeneralsClient.CategoryHolder.GENERALS.label().getString().equals("Generals"))throw new IllegalStateException("Untranslated controls category");checks.add("The controls category has a translated readable name");work=CompletableFuture.runAsync(()->{try{NativeVersionReuseBench.connect();}catch(Exception e){throw new CompletionException(e);}});next(1);}
  else if(stage==1&&work.isDone()){work.join();String name="GeneralsQA";if(!NativeVersionReuseBench.openExisting(mc,name))mc.createWorldOpenFlows().createFreshLevel(name,new LevelSettings(name,GameType.CREATIVE,new LevelSettings.DifficultySettings(Difficulty.PEACEFUL,false,false),true,WorldDataConfiguration.DEFAULT),new WorldOptions(1263217L,false,false),lookup->lookup.lookupOrThrow(net.minecraft.core.registries.Registries.WORLD_PRESET).getOrThrow(WorldPresets.FLAT).value().createWorldDimensions(),MenuScreens.active(mc.screen));next(2);}
  else if(stage==2&&mc.player!=null&&mc.getSingleplayerServer()!=null){work=CompletableFuture.runAsync(()->{var s=mc.getSingleplayerServer();var l=s.getLevel(GeneralsMod.ARENA);s.getPlayerList().getPlayer(mc.player.getUUID()).teleportTo(l,.5,64,.5,Set.of(),0,60,false);WorldRules.get(l).update(WorldRules.Values.defaults().toggle("naturalResources"));if(Boolean.getBoolean("generalsmc.feedbackRegression")){WorldRules.get(l).update(WorldRules.Values.defaults().toggle("naturalResources").toggle("blockDestruction").toggle("environmentDamage"));for(int x=12;x<=62;x++)for(int z=-20;z<=20;z++){for(int y=58;y<64;y++)l.setBlock(new BlockPos(x,y,z),net.minecraft.world.level.block.Blocks.SANDSTONE.defaultBlockState(),3);for(int y=64;y<72;y++)l.setBlock(new BlockPos(x,y,z),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);}}l.setBlock(new BlockPos(24,64,24),SiteBlocks.SUPPLY.defaultBlockState(),3);},mc.getSingleplayerServer());next(3);}
  else if(stage==3&&work.isDone()&&age>40&&mc.level.dimension().equals(GeneralsMod.ARENA)){work.join();checks.add("Fresh integrated server loads the mod dimension, rules, entities and marker block with modern codecs");NativeRtsController.toggle();if(NativeRtsController.hasSession())throw new IllegalStateException("Toggle started a game without a session");checks.add("The mode toggle is inactive before a match");if(Boolean.getBoolean("generalsmc.versionUxOnly")){next(8);return;}mc.setScreen(new GeneralsSetupScreen(null));click(mc,"Свободная игра");((NativeLaunchScreen)MenuScreens.active(mc.screen)).faction="FactionChinaTankGeneral";click(mc,"Начать");next(4);}
  else if(stage==4&&NativeWorldView.current!=null&&NativeWorldView.current.state!=null&&NativeWorldView.current.scene!=null&&NativeWorldView.current.state.frame()>100&&age>100){var v=NativeWorldView.current;if(Boolean.getBoolean("generalsmc.feedbackRegression")&&!feedbackComplete){if(!NativeVersionCombatBench.tick(mc,checks,name->{Files.deleteIfExists(mc.gameDirectory.toPath().resolve("screenshots").resolve(name));Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),1,c->{});}))return;feedbackComplete=true;}if(v.scene.batches().isEmpty()||v.drawnVertices==0||!v.fog.shaderReady)throw new IllegalStateException("New world pipeline or depth fog did not draw");Files.deleteIfExists(mc.gameDirectory.toPath().resolve("screenshots/version-native-world.png"));Screenshot.grab(mc.gameDirectory,"version-native-world.png",mc.getMainRenderTarget(),1,c->{});checks.add("Original engine models, marker and backend render pipelines plus depth-projected shroud draw in the actual Minecraft world");var a=v.state.objects().stream().filter(o->o.owner()==2&&o.template().contains("Dozer")).findFirst().orElseThrow();unit=a.id();var base=v.state.objects().stream().filter(o->o.owner()==2&&o.structure()).findFirst().orElseThrow();double dx=a.x()-base.x(),dz=a.y()-base.y(),length=Math.max(.01,Math.hypot(dx,dz));facing=a.orientation();before=v.origin.world(a.x(),a.y(),a.z());goal=before.add(dx/length*6,0,dz/length*6);v.cameraX=goal.x;v.cameraZ=goal.z;v.session.select(unit);next(5);}
  else if(stage==5&&age>80){var v=NativeWorldView.current;var actor=v.state.objects().stream().filter(o->o.id()==unit).findFirst().orElseThrow();before=v.origin.world(actor.x(),actor.y(),actor.z());facing=actor.orientation();double ground=WorldSurface.ground(mc.level,(int)Math.floor(goal.x),(int)Math.floor(goal.z));if(!Double.isFinite(ground))throw new IllegalStateException("Move probe target is not loaded");goal=new Vec3(goal.x,ground,goal.z);var screen=(NativeWorldScreen)MenuScreens.active(mc.screen);var p=screen.project(goal);var e=new MouseButtonEvent(p[0],p[1],new MouseButtonInfo(0,0));commandFrame=NativeWorldView.current.state.frame();command=System.nanoTime();screen.mouseMoved(p[0],p[1]);screen.mouseClicked(e,false);screen.mouseReleased(e);next(6);}
  else if(stage==6){var v=NativeWorldView.current;var a=v.state.objects().stream().filter(o->o.id()==unit).findFirst().orElseThrow();var now=v.origin.world(a.x(),a.y(),a.z());if(translationResponse<0&&now.distanceTo(before)>.05)translationResponse=(System.nanoTime()-command)/1_000_000;if(response<0&&(now.distanceTo(before)>.05||Math.abs(Math.IEEEremainder(a.orientation()-facing,Math.PI*2))>.01))response=(System.nanoTime()-command)/1_000_000;if(v.state.frame()-commandFrame>=140||age>300){if(now.distanceTo(goal)>1.2||response<0||response>1000)throw new IllegalStateException("Modern RTS move failed "+now+" -> "+goal+" response "+response);checks.add("Real modern mouse LMB order moves the original dozer to the clicked world point");v.cameraX+=100;next(60);}}
  else if(stage==60&&age>40&&mc.level.hasChunkAt(BlockPos.containing(NativeWorldView.current.cameraX,64,NativeWorldView.current.cameraZ))){Files.deleteIfExists(mc.gameDirectory.toPath().resolve("screenshots/version-unexplored-ground.png"));Screenshot.grab(mc.gameDirectory,"version-unexplored-ground.png",mc.getMainRenderTarget(),1,c->{});checks.add("Unexplored ground is captured for depth-shroud visual verification after moving the camera into newly loaded chunks");NativeRtsController.toggle();walkStart=mc.player.position();net.minecraft.client.KeyMapping.set(net.fabricmc.fabric.api.client.keymapping.v1.KeyMappingHelper.getBoundKeyOf(mc.options.keyUp),true);next(7);}
  else if(stage==7&&age>20){if(!walkingChecked){walkingChecked=true;net.minecraft.client.KeyMapping.set(net.fabricmc.fabric.api.client.keymapping.v1.KeyMappingHelper.getBoundKeyOf(mc.options.keyUp),false);if(MenuScreens.active(mc.screen)!=null||mc.player.position().distanceTo(walkStart)<1)throw new IllegalStateException("Minecraft walk failed: "+walkStart+" -> "+mc.player.position());checks.add("Returning to ordinary Minecraft restores its actual movement bindings");}if(!NativeVersionDrivingBench.tick(mc,checks))return;NativeRtsController.stop();next(8);}
  else if(stage==8&&NativeVersionUxBench.tick(mc,checks)){next(9);}
  else if(stage==9&&age>20){if(Boolean.getBoolean("generalsmc.versionUxOnly")){finish(mc,"PASS",null);return;}var dir=mc.gameDirectory.toPath().resolve("screenshots");if(!Files.exists(dir.resolve("version-unexplored-ground.png"))){if(age>100)throw new IllegalStateException("Missing shroud screenshot");return;}double near=brightness(dir.resolve("version-native-world.png"),true),far=brightness(dir.resolve("version-unexplored-ground.png"),false);if(far<40||far>140||near<far*1.7)throw new IllegalStateException("Depth shroud pixels failed, visible="+near+", unexplored="+far);checks.add("Saved frame pixels keep explored ground bright and unexplored ground visibly dim: "+Math.round(near)+" / "+Math.round(far));finish(mc,"PASS",null);}
 }catch(Throwable error){GeneralsMod.LOG.error("Version oracle failed",error);finish(mc,"FAIL",error.toString());}}
 static double brightness(Path file,boolean near)throws Exception{try(var stream=Files.newInputStream(file);var image=com.mojang.blaze3d.platform.NativeImage.read(stream)){long sum=0,count=0;int xEnd=near?image.getWidth()/8:image.getWidth()-24,yBegin=near?image.getHeight()/3:24,yEnd=near?image.getHeight()/2:image.getHeight()*5/8;for(int y=yBegin;y<yEnd;y+=8)for(int x=24;x<xEnd;x+=8){sum+=(image.getPixel(x,y)>>16)&255;count++;}return (double)sum/count;}}
 static void finish(Minecraft mc,String result,String error){done=true;try{Files.createDirectories(Path.of(System.getProperty("generalsmc.evidence","evidence")));Files.writeString(Path.of(System.getProperty("generalsmc.evidence","evidence"),"native-version-tests.json"),GeneralsMod.JSON.toJson(Map.of("minecraft",System.getProperty("generalsmc.testVersion","private"),"scope",Boolean.getBoolean("generalsmc.versionUxOnly")?"UI":"RTS and UI","result",result,"stage",stage,"checks",checks,"root",String.valueOf(root),"responseMillis",response,"translationMillis",translationResponse,"error",error==null?"":error)));}catch(Exception writeError){GeneralsMod.LOG.error("Version evidence could not be saved",writeError);}NativeRtsController.stop();mc.stop();}
